.darma-loader-tw-toast-slide { position: relative; overflow: hidden; width: var(--loader-size, 180px); height: calc(var(--loader-size, 180px) * .4); }
.darma-loader-tw-toast-slide .darma-loader-tw-toast-slide__toast { position: absolute; top: 0; bottom: 0; right: 0; display: flex; flex-direction: column; justify-content: center; gap: calc(var(--loader-size, 180px) * .05); width: 82%; padding: 0 calc(var(--loader-size, 180px) * .07); border-radius: calc(var(--loader-size, 180px) * .06); background: color-mix(in srgb, var(--loader-color, #10b981) 16%, transparent); border-left: calc(var(--loader-size, 180px) * .04) solid var(--loader-color, #10b981); box-sizing: border-box; animation: darma-loader-tw-toast-slide-twToast calc(var(--loader-speed, 1s) * 2.4) cubic-bezier(.4, 0, .2, 1) infinite; }
.darma-loader-tw-toast-slide .darma-loader-tw-toast-slide__toast i { height: calc(var(--loader-size, 180px) * .05); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color, #10b981) 45%, transparent); }
.darma-loader-tw-toast-slide .darma-loader-tw-toast-slide__toast i:last-child { width: 60%; }
@keyframes darma-loader-tw-toast-slide-twToast { 0% { transform: translateX(110%); opacity: 0; } 15%, 70% { transform: translateX(0); opacity: 1; } 90%, 100% { transform: translateX(110%); opacity: 0; } }

